/**
 * A request segment's text with the UI section the A2UI SDK generated kept
 * in its place as a bounded region, folded by default behind its label
 * line, "Generated by the A2UI SDK · Express · basic, v1.0"; unfolded, on a
 * faint neutral tint ending in a thin line. The developer's own text around
 * it stays plain. The prefix break's marker falling inside a section opens
 * it, and is drawn there as the marked text draws it.
 */
import {type ReactNode, useState} from 'react';

import {cn} from '@/lib/utils';
import type {UiSection} from '@/model/a2ui_step.ts';
import type {Marker} from '@/model/prefix.ts';
import {useBlockFold} from '@/state/block_folds.ts';

import {CopyButton} from './CopyButton.tsx';
import {Icon} from './icons.tsx';
import {BlockLabel} from './JsonBlock.tsx';

interface Piece {
  start: number;
  end: number;
  /** The label line of a UI section; none for the developer's own text. */
  label?: string;
}

function piecesOf(
  length: number,
  sections: readonly UiSection[],
  labelOf: (section: UiSection) => string,
): Piece[] {
  const pieces: Piece[] = [];
  let at = 0;
  for (const section of [...sections].sort((a, b) => a.start - b.start)) {
    if (section.start < at) continue;
    if (section.start > at) pieces.push({start: at, end: section.start});
    pieces.push({start: section.start, end: section.end, label: labelOf(section)});
    at = section.end;
  }
  if (at < length) pieces.push({start: at, end: length});
  return pieces;
}

export function SectionedText({
  label,
  meta,
  text,
  sections,
  labelOf,
  marker,
  mono,
}: {
  label: string;
  meta?: string;
  text: string;
  sections: readonly UiSection[];
  labelOf: (section: UiSection) => string;
  /** The prefix break, when it falls in this segment. */
  marker: Marker | undefined;
  mono: boolean;
}) {
  const fold = useBlockFold(label);
  const pieces = piecesOf(text.length, sections, labelOf);
  // The break's line sits after the text before it; the section holding it starts open.
  const breakAt = marker === undefined ? undefined : marker.before.length;
  const [opened, setOpened] = useState<ReadonlySet<number>>(() => new Set());
  const isOpen = (piece: Piece, index: number) =>
    opened.has(index) || (breakAt !== undefined && breakAt >= piece.start && breakAt < piece.end);
  const marked = (piece: Piece): ReactNode => {
    if (
      marker === undefined ||
      breakAt === undefined ||
      breakAt < piece.start ||
      breakAt >= piece.end
    ) {
      return text.slice(piece.start, piece.end);
    }
    const lineLength = marker.current.join('').length;
    const line = ([before, differing, after]: readonly [string, string, string]) => (
      <span className="min-w-0 break-words whitespace-pre-wrap">
        {before}
        <span className="rounded-sm bg-muted-foreground/25 px-0.5">{differing}</span>
        {after}
      </span>
    );
    return (
      <>
        {text.slice(piece.start, breakAt).replace(/\n$/, '')}
        <span
          role="separator"
          aria-label="Shared prefix ends"
          className="my-1 mb-1.5 flex items-center gap-2 font-sans text-xs font-semibold whitespace-nowrap text-muted-strong"
        >
          <span className="h-px flex-1 bg-muted-foreground" />
          Shared prefix ends
          <span className="h-px flex-1 bg-muted-foreground" />
        </span>
        <span className="mb-1.5 grid grid-cols-diff gap-x-2.5 gap-y-0.5">
          <span className="font-sans text-xs leading-5 text-muted-foreground">Earlier call</span>
          {line(marker.earlier)}
          <span className="font-sans text-xs leading-5 text-muted-foreground">This call</span>
          {line(marker.current)}
        </span>
        {text.slice(Math.min(piece.end, breakAt + lineLength), piece.end).replace(/^\n/, '')}
      </>
    );
  };
  return (
    <section
      data-anchor={marker === undefined ? undefined : 'prefix-break'}
      className="flex min-w-0 flex-col gap-1.5"
    >
      <BlockLabel label={label} meta={meta} fold={fold}>
        <CopyButton
          text={text}
          label={`Copy the ${label.toLowerCase()}`}
          className="h-6 px-1.5 text-xs"
        >
          Copy
        </CopyButton>
      </BlockLabel>
      {fold.open && (
        <div
          className={cn(
            'flex flex-col rounded-lg bg-tint px-3 py-2.5 break-words whitespace-pre-wrap',
            mono && 'font-mono text-xs leading-relaxed',
          )}
        >
          {pieces.map((piece, index) =>
            piece.label === undefined ? (
              <span key={index}>{marked(piece)}</span>
            ) : (
              <span key={index} className="my-1 flex flex-col">
                <button
                  type="button"
                  aria-expanded={isOpen(piece, index)}
                  onClick={() => {
                    const next = new Set(opened);
                    if (!next.delete(index)) next.add(index);
                    setOpened(next);
                  }}
                  className="ease-quick flex h-7 w-fit cursor-pointer items-center gap-1.5 rounded-md pr-1.5 pl-1 font-sans text-xs font-semibold whitespace-nowrap text-muted-foreground hover:bg-border hover:text-foreground"
                >
                  <Icon kind={isOpen(piece, index) ? 'chevronDown' : 'chevronRight'} size={12} />
                  {piece.label}
                </button>
                {isOpen(piece, index) && (
                  <span className="rounded-md border-b border-border bg-foreground/4 px-2 py-1.5">
                    {marked(piece)}
                  </span>
                )}
              </span>
            ),
          )}
        </div>
      )}
    </section>
  );
}
